    @media print {
        .sidebar, .topbar, .sidebar-overlay, #pageLoader, #navProgress,
        .mobile-bottom-nav, #scrollTop, #globalToastWrap,
        .btn, .dropdown, form[action*="logout"] { display: none !important; }
